package com.yeyamo_mobile.api.booking_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="booking_command_receipts")public class CommandReceiptEntity{@Id private UUID id;@Column(name="idempotency_key",nullable=false,length=160)private String key;@Column(name="user_id",nullable=false,length=120)private String userId;@Column(nullable=false,length=80)private String operation;@ManyToOne(fetch=FetchType.EAGER,optional=false)@JoinColumn(name="booking_id")private BookingEntity booking;@Column(name="created_at",nullable=false)private Instant createdAt;protected CommandReceiptEntity(){}public CommandReceiptEntity(String key,String user,String operation,BookingEntity booking){id=UUID.randomUUID();this.key=key;userId=user;this.operation=operation;this.booking=booking;createdAt=Instant.now();}public BookingEntity getBooking(){return booking;}}
